<!doctype html><html <?php language_attributes(); ?>><head><meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width,initial-scale=1"><?php wp_head(); ?></head><body <?php body_class(); ?>><?php wp_body_open(); $route=is_front_page()?'index':get_post_field('post_name',get_queried_object_id()); $allowed=['index','about','services','homes','installments','faq','contact']; if(in_array($route,$allowed,true)){include get_template_directory().'/content-'.$route.'.php';}else{echo '<main class="section">';while(have_posts()){the_post();the_title('<h1>','</h1>');the_content();}echo '</main>';} wp_footer(); ?></body></html>